        waitlist_entry = self.conn.execute("SELECT * FROM waitlist WHERE counselor_id=? AND start_time=? AND status='WAITING' ORDER BY waitlist_id ASC", (counselor_id, start_time)).fetchone()
        while waitlist_entry:
