                self.conn.execute("INSERT INTO slots VALUES (?, ?, ?, ?)", (slot_id, counselor_id, start_time, "AVAILABLE"))
        except sqlite3.IntegrityError:
            # This is a bit tricky because slot_id is UUID, but the brief says duplicate (counselor_id, start_time) should raise ValueError.
