                                   (waitlist_entry['client_email'], booking_id, "USE", -1, f"promote_{booking_id}"))
                self.conn.execute("INSERT INTO bookings VALUES (?, ?, ?, ?, ?, ?, ?)", (booking_id, slot['counselor_id'], slot['start_time'], waitlist_entry['client_name'], waitlist_entry['client_email'], "CONFIRMED", None))
